def pre_suggestion_filter_icon(source):
    from suggestion_description_scope_contract import pre_suggestion_description
    source = pre_suggestion_description(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_filter_icon_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_filter_icon(data.decode()).encode() if path.suffix == '.swift' else data

